mapper.select:
select b.id, b.bill_no, b.site_id, b.qty, b.alarm_level, b.status, b.del_flag, b.create_by, b.create_time, b.update_by, b.update_time, b.remark, s.site_no as siteNo, s.site_name as siteName, s.area_name as areaName from t_rad_alarm_bill b left join t_rad_site s on s.id = b.site_id where b.del_flag = 0
and b.site_id = #{siteId}
and b.status = #{status}
and b.bill_no like concat('%', #{billNo}, '%')
order by b.create_time desc, b.id desc
